using System.Collections.Generic;
using System.Linq;

public class TestClass
{
    /// <summary>Validates filtered values.</summary>
    /// <param name="values">The values to filter.</param>
    /// <exception cref="System.ArgumentNullException">
    /// Thrown when <paramref name="values"/> is null.
    /// </exception>
    public void M(IEnumerable<object?> values)
    {
        System.ArgumentNullException.ThrowIfNull(values);

        foreach (string value in GetStrings(values))
        {
            Validate(value);
        }
    }

    private static IEnumerable<string> GetStrings(
        IEnumerable<object?> values)
    {
        return values.OfType<string>();
    }

    private static void Validate(string? value)
    {
        System.ArgumentNullException.ThrowIfNull(value);
    }
}

