using System.Collections.Generic;
using System.Linq;

public sealed class TestClass
{
    /// <summary>Validates resolved values.</summary>
    public void M(object? candidate)
    {
        IReadOnlyList<string> values = Resolve(candidate);

        foreach (string value in values)
        {
            Validate(value);
        }
    }

    private static IReadOnlyList<string> Resolve(object? candidate)
    {
        Dictionary<string, string> values =
            new(StringComparer.Ordinal);

        TryAdd(candidate, values);

        return values.Values
            .OrderBy(static value => value, StringComparer.Ordinal)
            .ToArray();
    }

    private static void TryAdd(
        object? candidate,
        Dictionary<string, string> values)
    {
        if (candidate is not string value)
        {
            return;
        }

        values.TryAdd(value, value);
    }

    private static void Validate(string? value)
    {
        ArgumentNullException.ThrowIfNull(value);
    }
}

