using System;

public static class EntryPoint
{
    public static void M(
        bool useReplacement,
        bool clear)
    {
        Item? normalized =
            Normalize(
                new Item(),
                useReplacement);

        if (clear)
        {
            normalized = null;
        }

        Validate(
            normalized);
    }

    private static Item? Normalize(
        Item? item,
        bool useReplacement)
    {
        if (useReplacement)
